#include <stdio.h>

struct Player {
    char name[10];
    int hp;
};

void heal(struct Player *p) {
    (*p).hp += 10;
    p->hp += 10;
}

int main() {
    struct Player warrior = {"Conan", 50};

    printf("HP: %d\n", warrior.hp);
    heal(&warrior);
    printf("HP: %d\n", warrior.hp);

    return 0;
}
